import { useCallback, useEffect, useState } from 'react';

import { trainings } from 'pages/trainingHub/__mock__/content';
import { Pillar, Training, TrainingHubData } from 'pages/trainingHub/domain';

export const useTrainingData = () => {
  const [trainingData] = useState<TrainingHubData>(trainings);
  const [recentlyAddedTrainings, setRecentlyAddedTrainings] = useState<
    Training[]
  >([]);

  const getTraining = useCallback(
    (pillar: string, id: string) => {
      const training = (() => {
        if (pillar) {
          return trainingData[pillar as keyof TrainingHubData]?.trainings.find(
            (training: Training) => training.id === id,
          );
        }
        return Object.values(trainingData)
          .find((pillar: Pillar) =>
            pillar?.trainings?.find((training: Training) => training.id === id),
          )
          ?.trainings.find((training: Training) => training.id === id);
      })();
      return training;
    },
    [trainingData],
  );

  useEffect(() => {
    const recentlyAddedTrainings = Object.values(trainingData)
      .flatMap((pillar: Pillar) => pillar.trainings)
      .sort(
        (a: Training, b: Training) =>
          new Date(b.accessedAt).getTime() - new Date(a.accessedAt).getTime(),
      );
    setRecentlyAddedTrainings(recentlyAddedTrainings);
  }, [trainingData]);

  return {
    trainingData,
    recentlyAddedTrainings,
    getTraining,
  };
};
